// LSH room-service.order → a ready-to-send alert line for the kitchen/staff.
const b = $input.first().json.body || {};
const o = b.data || {};
const items = (o.items || []).map(i => i.qty + '× ' + i.name).join(', ');
const pay = o.payment === 'card' ? 'paid by card' : 'to room';
const summary = '🛎️ Room ' + (o.room || '?') + ': ' + items + ' = ' + o.total + ' ' + o.currency + ' (' + pay + ')' + (o.note ? ' — note: ' + o.note : '');
return [{ json: { event: b.event, hub: b.hub, summary, order: o } }];
